1	<!doctype html>
2	<html lang="it">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Vela — Viaggi di padel e tennis con hotel</title>
7	<meta name="description" content="Dì cosa vuoi: Vela prenota il tuo viaggio di padel o tennis con hotel. Una sola proposta, a parole tue.">
8	<style>
9	:root{
10	  --accent:#0071e3;
11	  --text:#1d1d1f;
12	  --text-2:#6e6e73;
13	  --link:#0066cc;
14	  --bg:#ffffff;
15	  --bg-hero:#fbfbfd;
16	  --bg-alt:#f5f5f7;
17	  --bubble-in:#e9e9eb;
18	  --line:#d2d2d7;
19	  --line-soft:#e5e5ea;
20	  --radius-card:28px;
21	  --content:1120px;
22	  --font:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue",Helvetica,Arial,sans-serif;
23	  --mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
24	}
25	*{box-sizing:border-box}
26	html{scroll-behavior:smooth}
27	body{margin:0;font-family:var(--font);background:var(--bg);color:var(--text);-webkit-font-smoothing:antialiased}
28	a{color:var(--link);text-decoration:none}
29	a:hover{text-decoration:underline}
30	:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px}
31	.wrap{width:min(var(--content),100% - 32px);margin-inline:auto}
32	section{padding:120px 0;scroll-margin-top:52px}
33	.alt{background:var(--bg-alt)}
34	.eyebrow{font-size:21px;font-weight:600;color:var(--accent)}
35	h1,h2{margin:0;font-weight:700;color:var(--text)}
36	h2{font-size:56px;line-height:1.07;letter-spacing:-.025em}
37	.center{text-align:center}
38	.lead{font-size:21px;line-height:1.45;color:var(--text-2)}
39	.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 26px;border:0;border-radius:980px;background:var(--accent);color:#fff;font:500 17px/1 var(--font);cursor:pointer;text-decoration:none}
40	.btn:hover{text-decoration:none;filter:brightness(1.08)}
41	.card{background:var(--bg-alt);border-radius:var(--radius-card)}
42	.grid{display:grid;gap:24px}
43	.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
44	.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
45	
46	/* Nav */
47	.nav{position:sticky;top:0;z-index:10;height:52px;background:rgba(251,251,253,.8);backdrop-filter:saturate(180%) blur(20px);-webkit-backdrop-filter:saturate(180%) blur(20px);border-bottom:1px solid var(--line-soft)}
48	.nav .wrap{width:min(980px,100% - 32px);height:100%;display:flex;align-items:center;justify-content:space-between;gap:16px}
49	.brand{font-size:20px;font-weight:600;letter-spacing:-.02em;color:var(--text)}
50	.nav-links{display:flex;gap:32px;font-size:13px}
51	.nav-links a{color:var(--text)}
52	.nav-cta{font-size:12px;font-weight:500;color:#fff;background:var(--accent);padding:6px 14px;border-radius:980px}
53	.nav-cta:hover{text-decoration:none}
54	
55	/* Hero */
56	.hero{background:var(--bg-hero);padding:120px 0 110px;text-align:center}
57	.hero h1{margin-top:12px;font-size:88px;line-height:1.05;letter-spacing:-.03em}
58	.hero p{margin:28px auto 0;max-width:720px;font-size:24px;line-height:1.4;letter-spacing:-.01em;color:var(--text-2)}
59	.hero-ctas{margin-top:40px;display:flex;gap:28px;align-items:center;justify-content:center;flex-wrap:wrap}
60	.hero-ctas .more{font-size:19px}
61	.hero-chat{margin:80px auto 0;max-width:640px}
62	
63	/* Chat bubbles */
64	.chat{display:flex;flex-direction:column;gap:10px}
65	.b{max-width:80%;padding:11px 16px;font-size:16px;line-height:1.4;text-align:left}
66	.b.out{align-self:flex-end;background:var(--accent);color:#fff;border-radius:20px 20px 6px 20px}
67	.b.in{align-self:flex-start;background:#fff;color:var(--text);border-radius:20px 20px 20px 6px}
68	.hero-chat .chat{gap:12px}
69	.hero-chat .b{max-width:460px;padding:14px 20px;font-size:19px;line-height:1.35}
70	.hero-chat .b.out{border-radius:24px 24px 6px 24px}
71	.hero-chat .b.in{background:var(--bubble-in);border-radius:24px 24px 24px 6px}
72	.tool{align-self:center;display:flex;align-items:center;gap:8px;padding:6px 14px;border:1px solid var(--line);border-radius:980px;font-size:13px;font-weight:500;color:var(--text-2)}
73	
74	/* Come funziona */
75	.steps{margin-top:64px}
76	.step{background:#fff;border-radius:var(--radius-card);padding:44px 40px;min-height:280px;display:flex;flex-direction:column;gap:14px}
77	.step .n{font-size:48px;font-weight:700;letter-spacing:-.03em;color:var(--accent)}
78	.step h3{margin:0;font-size:28px;font-weight:600;letter-spacing:-.015em}
79	.step p{margin:0;font-size:19px;line-height:1.45;color:var(--text-2)}
80	
81	/* Esempi */
82	#esempi h2{margin-top:10px}
83	#esempi .lead{margin:24px auto 0;max-width:680px}
84	.examples{margin-top:64px}
85	.example{padding:40px 40px 36px;display:flex;flex-direction:column}
86	.example .tag{font-size:13px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--text-2)}
87	.example h3{margin:10px 0 24px;font-size:24px;font-weight:600;letter-spacing:-.015em}
88	
89	/* Con Claude */
90	.claude-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:80px;align-items:center}
91	.claude-grid h2{margin-top:10px}
92	.claude-grid ol{margin:32px 0 0;padding-left:24px;display:flex;flex-direction:column;gap:14px;font-size:19px;line-height:1.45}
93	.connector{background:#fff;border-radius:var(--radius-card);padding:48px 44px;display:flex;flex-direction:column;gap:20px}
94	.connector label,.connector .small{font-size:14px;font-weight:600;color:var(--text-2)}
95	.url-row{display:flex;gap:10px;align-items:center}
96	.url-row input{flex:1;min-width:0;height:52px;padding:0 18px;border:1px solid var(--line);border-radius:14px;background:#fff;font:15px var(--mono);color:var(--text)}
97	.url-row .btn{height:52px;min-width:104px;padding:0 22px}
98	.connector .sep{margin-top:12px;padding-top:24px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:12px}
99	.connector .b.in{background:var(--bg-alt);font-size:17px;padding:12px 18px;max-width:100%}
100	
101	/* A voce / Al telefono */
102	.channels{margin-top:64px}
103	.channel{border-radius:var(--radius-card);padding:56px 52px;min-height:420px;display:flex;flex-direction:column;gap:18px}
104	.channel h3{margin:12px 0 0;font-size:40px;font-weight:700;letter-spacing:-.02em}
105	.channel p{margin:0;font-size:21px;line-height:1.4}
106	.channel .soon{margin-top:auto;align-self:flex-start;padding:8px 16px;border-radius:980px;font-size:14px;font-weight:500}
107	.channel.dark{background:#000;color:#f5f5f7}
108	.channel.dark p{color:#a1a1a6}
109	.channel.dark .soon{border:1px solid #48484a;color:#d2d2d7}
110	.channel.light{background:var(--bg-alt)}
111	.channel.light p{color:var(--text-2)}
112	.channel.light .soon{border:1px solid var(--line);color:var(--text-2)}
113	
114	/* Repository */
115	.repo-section{padding:96px 0}
116	.repo{background:#fff;border-radius:var(--radius-card);padding:48px 56px;display:flex;align-items:center;justify-content:space-between;gap:40px}
117	.repo-info{display:flex;align-items:center;gap:28px}
118	.repo-icon{width:64px;height:64px;flex-shrink:0;border-radius:16px;background:var(--text);display:flex;align-items:center;justify-content:center}
119	.repo-title{font-size:32px;line-height:1.15;letter-spacing:-.02em}
120	.repo p{margin:6px 0 0;font-size:17px;color:var(--text-2)}
121	.repo code{font:15px var(--mono);color:var(--text)}
122	.btn-dark{background:var(--text);flex-shrink:0}
123	
124	/* Footer */
125	footer{background:var(--bg-alt)}
126	footer .wrap{padding:24px 0 40px;border-top:1px solid var(--line);font-size:12px;color:var(--text-2)}
127	
128	/* Responsive */
129	@media (max-width:1068px){
130	  .hero h1{font-size:72px}
131	  h2{font-size:48px}
132	  .claude-grid{gap:48px}
133	}
134	@media (max-width:834px){
135	  section{padding:88px 0}
136	  .hero{padding:88px 0 80px}
137	  .hero h1{font-size:56px}
138	  .hero p{font-size:21px}
139	  h2{font-size:40px}
140	  .g2,.g3,.claude-grid{grid-template-columns:minmax(0,1fr)}
141	  .nav-links{display:none}
142	  .step{min-height:0}
143	  .channel{min-height:320px;padding:44px 36px}
144	  .repo{flex-direction:column;align-items:flex-start;padding:36px 28px}
145	  .repo-info{flex-direction:column;align-items:flex-start;gap:20px}
146	}
147	@media (max-width:480px){
148	  .hero h1{font-size:44px}
149	  h2{font-size:34px}
150	  .example,.connector{padding:28px 20px}
151	  .url-row{flex-direction:column;align-items:stretch}
152	  .b{max-width:88%}
153	}
154	@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
155	</style>
