input.command:
python3 - <<'EOF'
p="landing/main.js"; s=open(p).read()
old=s[s.index("  function selectText(node) {"):s.index("  function showVoice")]
new='''  function setUpCopy(url) {
    const input = document.getElementById("mcp-url");
    const button = document.getElementById("copy-mcp");
    let timer;
    if (url) input.value = url;
    button.hidden = false;
    button.addEventListener("click", function () {
      if (!navigator.clipboard || !window.isSecureContext) {
        input.select();
        return;
      }
      navigator.clipboard.writeText(input.value).then(function () {
        button.textContent = "Copiato";
        clearTimeout(timer);
        timer = setTimeout(function () { button.textContent = "Copia"; }, 2000);
      }, function () {
        input.select();
      });
    });
  }

'''
s=s.replace(old,new)
open(p,"w").write(s)
EOF
